DROP TABLE IF EXISTS core_document_m;

CREATE TABLE core_document_m
(
    doc_id VARCHAR(128) PRIMARY KEY NOT NULL,
    doc_name VARCHAR(256) NOT NULL,
    doc_type VARCHAR(128) NOT NULL,
    registration_code VARCHAR(32) NOT NULL,
    country_state_id VARCHAR(128) NOT NULL,
    vehicle_type_id VARCHAR(32) NOT NULL,
    is_deleted TINYINT NOT NULL DEFAULT False,
    created_by BIGINT NOT NULL,
    created_time TIMESTAMP DEFAULT NOW()
);

